Problem:
A construction site can use two transfer methods to move equipment using cranes or elevators. Each crane can transport 5 units of equipment and costs $2000 per hour. Each elevator can transport 2 units of equipment and costs $500 per hour. The construction site needs to transport at least 90 units of equipment and has available $30000. There must be at least three times more elevators than cranes. How many of each type of transfer method should be done to minimize the total number of transfer methods?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "cranes",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "elevators",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "cranes",
     "coef": 1.0
    },
    {
     "var": "elevators",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "capacity",
    "terms": [
     {
      "var": "cranes",
      "coef": 5.0
     },
     {
      "var": "elevators",
      "coef": 2.0
     }
    ],
    "sense": ">=",
    "rhs": 90.0
   },
   {
    "name": "budget",
    "terms": [
     {
      "var": "cranes",
      "coef": 2000.0
     },
     {
      "var": "elevators",
      "coef": 500.0
     }
    ],
    "sense": "<=",
    "rhs": 30000.0
   },
   {
    "name": "elevator_ratio",
    "terms": [
     {
      "var": "elevators",
      "coef": 1.0
     },
     {
      "var": "cranes",
      "coef": -3.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 33.0,
  "values": {
   "cranes": 8.0,
   "elevators": 25.0
  },
  "binding": [
   "capacity"
  ],
  "slack": {
   "capacity": 0.0,
   "budget": 1500.0,
   "elevator_ratio": 1.0
  },
  "shadow_prices": null,
  "limits": {
   "capacity": {
